/* Original Linux 6.6.143 arch/arm64/kernel/proton-pack.c forms.
 * These are target-owned source ISA, not instructions generated by Core. */
typedef unsigned long u64;

__attribute__((noinline)) void qcom_link_stack_sanitisation(void) {
    u64 tmp;
    asm volatile("mov %0, x30\n"
                 ".rept 16\n"
                 "bl . + 4\n"
                 ".endr\n"
                 "mov x30, %0\n"
                 : "=&r"(tmp));
}

__attribute__((noinline)) void spectre_v4_toggle_ssbs(void) {
    asm volatile(".inst (0xd500401f | ((3) << 16 | (1) << 5) | ((!!(1)) << 8))\n\t");
    asm volatile(".inst (0xd500401f | ((3) << 16 | (1) << 5) | ((!!(0)) << 8))\n\t");
}
